"""Baked residential style options + compatibility matrices.

Generated from the reference partner spreadsheets (Color/Wood/Varnish/Glaze
compatibility matrix and the doors/drawers catalog). Do NOT hand-edit -- this
file is regenerated from source data. Pure data + plain lookup helpers so the
runtime needs no spreadsheet libraries.

Cascades:
  wood  -> colors        (WOOD_TO_COLORS)
  color -> varnishes      (COLOR_TO_VARNISHES; stain colors only)
  color -> glazes         (COLOR_TO_GLAZES)
  overlay -> hinges       (OVERLAY_TO_HINGES; [code, desc, is_default])
  door/drawer series -> shape -> panel -> product code (DOOR/DRAWER_CASCADE)
"""

