def colors_for_wood(wood):
    """Colors compatible with a wood specie (falls back to all colors)."""
    return WOOD_TO_COLORS.get(wood, sorted(COLORS))


def varnishes_for_color(color):
    """Varnishes compatible with a color (empty for non-stain colors)."""
    return COLOR_TO_VARNISHES.get(color, [])


def glazes_for_color(color):
    """Glazes compatible with a color."""
    return COLOR_TO_GLAZES.get(color, ["*None"])


def hinges_for_overlay(overlay):
    """[code, desc, is_default] hinge rows for an overlay."""
    return OVERLAY_TO_HINGES.get(overlay, [])


def default_hinge_for_overlay(overlay):
    for code, desc, is_default in OVERLAY_TO_HINGES.get(overlay, []):
        if is_default:
            return code
    rows = OVERLAY_TO_HINGES.get(overlay, [])
    return rows[0][0] if rows else ""


def door_shapes(series, drawer=False):
    cas = DRAWER_CASCADE if drawer else DOOR_CASCADE
    return sorted(cas.get(series, {}))


def door_panels(series, shape, drawer=False):
    cas = DRAWER_CASCADE if drawer else DOOR_CASCADE
    return sorted(cas.get(series, {}).get(shape, {}))


def door_code(series, shape, panel, drawer=False):
    cas = DRAWER_CASCADE if drawer else DOOR_CASCADE
    return cas.get(series, {}).get(shape, {}).get(panel, "")

def door_description(series, shape, panel, drawer=False):
    """The catalog's own name for a pick (its Description column, less
    the "Door - " / "Drawer - " lead), e.g. "Shaker Recessed Solid Wood
    Panel" for Shaker / Square / Solid Wood Recessed. "" when the pick
    has no code or the code no description."""
    table = DRAWER_DESCRIPTIONS if drawer else DOOR_DESCRIPTIONS
    return table.get(door_code(series, shape, panel, drawer), "")


