def special_effects_for(wood, color):
    """Special effects available for a wood + color (catalog
    intersection). Empty when the combination has no compatible
    effects."""
    w = set(WOOD_TO_SPECIAL_EFFECTS.get(wood, ()))
    return sorted(e for e in COLOR_TO_SPECIAL_EFFECTS.get(color, ())
                  if e in w)


